import numpy as np

def solve(input_grid):
    # Step 1: Extract colored cells by color
    in_pos = {}
    for r in range(len(input_grid)):
        for c in range(len(input_grid[0])):
            color = input_grid[r][c]
            if color != 0:
                if color not in in_pos:
                    in_pos[color] = []
                in_pos[color].append((r, c))

    # Step 2: Determine color rank by min_col
    color_ranks = {}
    for color in in_pos:
        min_col = min(set(c for r, c in in_pos[color]))
        if color not in color_ranks:
            color_ranks[color] = min_col

    # Sort colors by min_col to get ranks
    sorted_colors = sorted(color_ranks.keys(), key=lambda c: color_ranks[c])
    color_rank = {c: i for i, c in enumerate(sorted_colors)}

    # Step 3: Assign target columns based on rank
    target_cols = {
        0: [10, 11],  # rank 0 gets leftmost + 11
        1: [11, 12],  # rank 1 gets middle + right
        2: [11, 12],  # rank 2 gets middle + right
        3: [12],      # rank 3 special: just right
        4: [11, 12],  # rank 4+ gets middle + right
    }

    # Create output
    output_grid = [[0] * 13 for _ in range(10)]

    for color in in_pos:
        rank = color_rank[color]
        cols_list = target_cols.get(rank, [11, 12])  # Default to middle + right

        cells = in_pos[color]
        # Sort cells by input column
        cells_sorted = sorted(cells, key=lambda x: x[1])

        # Determine row shift
        cells_out = []
        for r, c in cells_sorted:
            if r < 6:
                r_out = r + 1
            else:
                r_out = r

            # Map to output column
            # Within target columns, cells are placed in order
            if len(cells_sorted) <= len(cols_list):
                c_out = cols_list[cells_sorted.index((r, c))]
            else:
                # More cells than columns - assign cyclically
                c_out = cols_list[(cells_sorted.index((r, c)) + cells_sorted.index((r, c))) % len(cols_list)]

            cells_out.append((r_out, c_out))

        # Write to output grid
        # Sort so we handle conflicts correctly
        cells_out.sort()
        for r_out, c_out in cells_out:
            if r_out < 10:
                output_grid[r_out][c_out] = color

    return output_grid

